style.css:
@-moz-document domain("320yt.com") {
body {
    background-color: #0a0a0a;
    color: #bbc2c9;
}
.bg-theme {
    background-color: #101010;
}
.bg-primary {
    background-color: #04283f!important;
}
.text-dark {
    color: #dbdee1!important;
}
.btn-primary {
    background-color: #04283f!important;
    border-color: #04283f!important;
}
a.text-dark:focus, a.text-dark:hover {
    color: #dbdee1!important;
}
.icon-size i {
    background-color: #031f30;
}
.has-search .form-control {
    border-color: #04283f!important;
}
.form-control {
    color: #cdd1d5;
    background-color: #101010;
    border-color: #333;
}
.form-control:focus {
    color: #eee;
    background-color: #101010;
}
.form-control:disabled, .form-control[readonly] {
    background-color: #20262c;
    opacity: 1;
}
.border-bottom {
    border-bottom-color: #25252!important;
}
.has-search:focus-within {
    box-shadow: 0 0 10px #101010!important;
}
.icon-size {
    color: #768a9e!important;
}
.card {
    background-color: #0a0a0a;
    border: 1px solid rgba(255, 255, 255, .125);
}
.dropdown-menu {
    background-color: #0a0a0a;
    border: 1px solid rgba(255, 255, 255, .15);
}
.dropdown-item {
    color: #eee;
}

/* FOOTER */
.bg-light {
    background-color: #080a0c!important;
}
}
